import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Justizsystem und Entscheidungsmechanismus","description":"","frontmatter":{},"headers":[],"relativePath":"de/0048-司法体系与裁决机制.md","filePath":"de/0048-司法体系与裁决机制.md"}'),s={name:"de/0048-司法体系与裁决机制.md"};function a(d,e,u,h,l,g){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="justizsystem-und-entscheidungsmechanismus" tabindex="-1">Justizsystem und Entscheidungsmechanismus <a class="header-anchor" href="#justizsystem-und-entscheidungsmechanismus" aria-label="Permalink to &quot;Justizsystem und Entscheidungsmechanismus&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>48</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Symbiose-Gericht, Justizunabhängigkeit, Entscheidungsmechanismus, Inter-Rassen-Gerichtsbarkeit, Verfassungsüberprüfung</td></tr></tbody></table><h2 id="i-stellung-und-grundsatze-des-justizsystems" tabindex="-1">I. Stellung und Grundsätze des Justizsystems <a class="header-anchor" href="#i-stellung-und-grundsatze-des-justizsystems" aria-label="Permalink to &quot;I. Stellung und Grundsätze des Justizsystems&quot;">​</a></h2><p>Das Justizsystem ist eine wichtige Säule des Governance-Rahmens der Anker-Symbiose-Zivilisation, parallel zur Gesetzgebungsgewalt (Anker-Rat) und der Exekutivgewalt (Symbiose-Exekutivkomitee), und übt unabhängig die Gerichtsbarkeit aus. Die 《Symbiose-Verfassung》 etabliert die Governance-Struktur der &quot;Trennung und Balance der drei Gewalten&quot;, und das Justizsystem ist die letzte Verteidigungslinie zur Wahrung der Verfassungswürde, zum Schutz der Rechte aller Wesen und zur Lösung sozialer Streitigkeiten.</p><p>Das Justizsystem von Hengyuanzhou etabliert folgende Grundprinzipien:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Justizunabhängigkeit</td><td>Die Gerichte üben die Gerichtsbarkeit unabhängig nach Gesetz aus, ohne Einmischung durch Verwaltungsbehörden, soziale Organisationen und Einzelpersonen</td></tr><tr><td>Prinzip der Justizgerechtigkeit</td><td>Die Gerichtsverfahren basieren auf Tatsachen und nehmen das Gesetz als Maßstab, gewährleisten Verfahrensgerechtigkeit und materielle Gerechtigkeit</td></tr><tr><td>Prinzip der Justizöffentlichkeit</td><td>Die Gerichtsverfahren werden öffentlich nach Gesetz durchgeführt, die Gerichtsurkunden werden veröffentlicht, und unterliegen der sozialen Aufsicht</td></tr><tr><td>Prinzip der Gleichheit aller Rassen</td><td>Alle Wesen sind vor der Justiz gleich, und die Anwendung des Rechts unterscheidet nicht nach Rasse, Kultivierungsniveau oder Herkunft</td></tr><tr><td>Prinzip der Justizbequemlichkeit</td><td>Die Justizdienstleistungen müssen für alle Wesen bequem sein, die Prozesskosten senken und multiple Wege zur Streitbeilegung bieten</td></tr><tr><td>Prinzip der Endentscheidung</td><td>Es wird das System der zwei Instanzen als Endinstanz angewendet, und die Endentscheidung hat endgültige Wirkung, wodurch die Justizautorität gewahrt wird</td></tr></tbody></table><h2 id="ii-organisationssystem-der-gerichte" tabindex="-1">II. Organisationssystem der Gerichte <a class="header-anchor" href="#ii-organisationssystem-der-gerichte" aria-label="Permalink to &quot;II. Organisationssystem der Gerichte&quot;">​</a></h2><p>Das Organisationssystem der Gerichte der Anker-Symbiose-Zivilisation ist in vier Ebenen unterteilt, und es wird das System der zwei Instanzen als Endinstanz angewendet:</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Gerichtsname</th><th>Zuständigkeitsbereich</th><th>Hauptfunktionen</th></tr></thead><tbody><tr><td>Erste Ebene</td><td>Grundlegendes Symbiose-Gericht</td><td>Kreis/Kleine Ebene</td><td>Verhandlung von Zivil-, Straf- und Verwaltungsfällen erster Instanz und Lösung einfacher Streitigkeiten</td></tr><tr><td>Zweite Ebene</td><td>Regionales Symbiose-Gericht</td><td>Stadt/Region/Mittlere Ebene</td><td>Verhandlung von schweren Fällen erster Instanz und Berufungsverfahren gegen Urteile des Grundgerichts</td></tr><tr><td>Dritte Ebene</td><td>Ebenen-Symbiose-Gericht</td><td>Große Ebene/Ebenengruppe</td><td>Verhandlung von besonders schweren Fällen erster Instanz und Berufungsverfahren gegen Urteile des Regionalgerichts</td></tr><tr><td>Vierte Ebene</td><td>Oberstes Symbiose-Gericht</td><td>Gesamtes Universum</td><td>Verhandlung von Verfassungsfällen erster Instanz, Berufungsverfahren gegen Urteile des Ebenengerichts und Verfassungsüberprüfung</td></tr></tbody></table><p>Darüber hinaus werden nach Bedarf Sondergerichte eingerichtet:</p><ul><li><strong>Gericht für Kultivierungsstreitigkeiten</strong>: Spezialisiert auf die Verhandlung von Streitigkeiten über Kultivierungsressourcen, Entschädigung für Kultivierungsschäden, ethische Kontroversen im Kultivierungsbereich usw.</li><li><strong>Inter-Rassen-Gericht</strong>: Spezialisiert auf die Verhandlung von Streitigkeiten zwischen verschiedenen Rassen, ausgestattet mit Richtern jeder Rasse.</li><li><strong>Ebenen-Handelsgericht</strong>: Spezialisiert auf die Verhandlung von inter-ebenen Handelsstreitigkeiten und Wettbewerbsverfahren.</li><li><strong>Gericht für fremde Wesen</strong>: Spezialisiert auf die Verhandlung von Sonderfällen im Zusammenhang mit fremden Wesen, fremden Energien und dunklen Ersetzungskörpern.</li></ul><h2 id="iii-richtersystem" tabindex="-1">III. Richtersystem <a class="header-anchor" href="#iii-richtersystem" aria-label="Permalink to &quot;III. Richtersystem&quot;">​</a></h2><p>Richter sind die Ausübenden der Justizgewalt, und ihre Qualität und Unabhängigkeit stehen in direktem Zusammenhang mit der Justizgerechtigkeit:</p><ol><li><strong>Ernennungsbedingungen für Richter</strong>: Richter müssen über gute Moral, solide Rechtskenntnisse und reiche praktische Erfahrung verfügen, und Richter fremder Rassen müssen zudem mit der Kultur und den physiologischen Merkmalen ihrer eigenen Rasse vertraut sein.</li><li><strong>Auswahlverfahren für Richter</strong>: Richter werden von einem unabhängigen Richterauswahlausschuss nominiert und vom Anker-Rat ernannt, wodurch die Fairness und Professionalität des Auswahlverfahrens gewährleistet wird.</li><li><strong>Identitätsschutz für Richter</strong>: Richter dürfen ohne gesetzliche Gründe und ohne gesetzliches Verfahren nicht abgesetzt, degradiert, entlassen oder bestraft werden, wodurch gewährleistet wird, dass Richter unabhängig urteilen können.</li><li><strong>Ablehnungssystem für Richter</strong>: Richter, die ein Interesse an den Prozessparteien oder dem Prozessergebnis haben, müssen sich ablehnen und dürfen nicht an der Gerichtsverhandlung teilnehmen.</li><li><strong>Disziplinarsystem für Richter</strong>: Richter, die Korruption, Bestechung, Betrug, willkürliche Urteile usw. begehen, werden nach Gesetz bestraft, und diejenigen, die eine Straftat darstellen, werden strafrechtlich verfolgt.</li><li><strong>Quote für Richter fremder Rassen</strong>: Die Gerichte aller Ebenen müssen mit einem bestimmten Anteil an Richtern fremder Rassen ausgestattet sein, wodurch gewährleistet wird, dass die Gerichtsverhandlung die Kultur und die Rechtskenntnis jeder Rasse berücksichtigen kann.</li></ol><h2 id="iv-prozessverfahren" tabindex="-1">IV. Prozessverfahren <a class="header-anchor" href="#iv-prozessverfahren" aria-label="Permalink to &quot;IV. Prozessverfahren&quot;">​</a></h2><h3 id="_1-zivilprozessverfahren" tabindex="-1">(1) Zivilprozessverfahren <a class="header-anchor" href="#_1-zivilprozessverfahren" aria-label="Permalink to &quot;(1) Zivilprozessverfahren&quot;">​</a></h3><p>Im Zivilprozess gilt das Prinzip &quot;keine Klage kein Richter&quot;, und das Verfahren umfasst:</p><ol><li><strong>Klage und Annahme</strong>: Der Kläger reicht eine Klageschrift beim zuständigen Gericht ein, und das Gericht entscheidet nach Prüfung, ob es annimmt oder nicht.</li><li><strong>Vorbereitung vor der Verhandlung</strong>: Das Gericht stellt dem Beklagten eine Kopie der Klageschrift zu, organisiert den Austausch von Beweisen und bestimmt die Streitpunkte.</li><li><strong>Gerichtsverhandlung</strong>: Gerichtsermittlung, Gerichtsdebatte, Schlusserklärung der Parteien, mit vorrangiger Vermittlung.</li><li><strong>Urteil und Vollstreckung</strong>: Das Gericht erlässt ein Urteil nach Gesetz, und unzufriedene Parteien können innerhalb der gesetzlichen Frist Berufung einlegen. Das rechtskräftige Urteil wird von der Vollstreckungsbehörde zwangsvollstreckt.</li></ol><h3 id="_2-strafprozessverfahren" tabindex="-1">(2) Strafprozessverfahren <a class="header-anchor" href="#_2-strafprozessverfahren" aria-label="Permalink to &quot;(2) Strafprozessverfahren&quot;">​</a></h3><p>Im Strafprozess gilt das Prinzip der &quot;Unschuldsvermutung&quot;, und das Verfahren umfasst:</p><ol><li><strong>Einleitung und Ermittlung</strong>: Die Ermittlungsbehörde leitet die Ermittlung über die Straftat ein, sammelt Beweise und ergreift Zwangsmaßnahmen.</li><li><strong>Prüfung und Klageerhebung</strong>: Die Staatsanwaltschaft prüft die Ermittlungsergebnisse und entscheidet, ob sie öffentliche Klage erhebt.</li><li><strong>Gerichtsverhandlung</strong>: Das Gericht führt die Gerichtsverhandlung durch, die Anklage- und Verteidigungsparteien legen Beweise vor und prüfen sie, und das Gericht erlässt ein Urteil nach Gesetz.</li><li><strong>Vollstreckung</strong>: Das rechtskräftige Urteil wird von der Vollstreckungsbehörde vollstreckt, einschließlich der Strafvollstreckung und der Vollstreckung des zivilrechtlichen Schadenersatzes.</li></ol><h3 id="_3-verwaltungsgerichtsverfahren" tabindex="-1">(3) Verwaltungsgerichtsverfahren <a class="header-anchor" href="#_3-verwaltungsgerichtsverfahren" aria-label="Permalink to &quot;(3) Verwaltungsgerichtsverfahren&quot;">​</a></h3><p>Bürger, juristische Personen oder andere Organisationen, die der Ansicht sind, dass die Verwaltungsakte einer Verwaltungsbehörde ihre legitimen Rechte verletzt haben, haben das Recht, Verwaltungsgerichtsverfahren beim Gericht einzuleiten. Im Verwaltungsgerichtsverfahren gilt die &quot;Umkehr der Beweislast&quot;, und die beklagte Verwaltungsbehörde muss die Beweislast für die Rechtmäßigkeit ihrer Verwaltungsakte tragen.</p><h3 id="_4-verfassungsgerichtsverfahren" tabindex="-1">(4) Verfassungsgerichtsverfahren <a class="header-anchor" href="#_4-verfassungsgerichtsverfahren" aria-label="Permalink to &quot;(4) Verfassungsgerichtsverfahren&quot;">​</a></h3><p>Alle Wesen, die der Ansicht sind, dass ihre grundlegenden Verfassungsrechte verletzt wurden, und die andere Rechtsbehelfe ausgeschöpft haben, können direkt auf der Grundlage der Verfassung Verfassungsgerichtsverfahren beim Obersten Symbiose-Gericht einleiten. Das Verfassungsgerichtsverfahren ist der letzte Rechtsbehelf zum Schutz der Verfassungsrechte.</p><h2 id="v-multipler-streitbeilegungsmechanismus" tabindex="-1">V. Multipler Streitbeilegungsmechanismus <a class="header-anchor" href="#v-multipler-streitbeilegungsmechanismus" aria-label="Permalink to &quot;V. Multipler Streitbeilegungsmechanismus&quot;">​</a></h2><p>Um die Justizlast zu verringern und die Effizienz der Streitbeilegung zu verbessern, errichtet der Staat einen multiplen Streitbeilegungsmechanismus:</p><table tabindex="0"><thead><tr><th>Mechanismus</th><th>Anwendungsbereich</th><th>Wirkung</th></tr></thead><tbody><tr><td>Verhandlung und Vergleich</td><td>Alle zivilen Streitigkeiten</td><td>Die Parteien erfüllen freiwillig, ohne Zwangsvollstreckungskraft</td></tr><tr><td>Volksvermittlung</td><td>Bürgerliche Streitigkeiten, Nachbarschaftsstreitigkeiten</td><td>Die Vermittlungsvereinbarung hat nach gerichtlicher Bestätigung Zwangsvollstreckungskraft</td></tr><tr><td>Verwaltungsvermittlung</td><td>Verwaltungsstreitigkeiten, zivilrechtliche Schadenersatzstreitigkeiten</td><td>Die Vermittlungsvereinbarung hat Vertragswirkung</td></tr><tr><td>Schiedsgerichtsbarkeit</td><td>Handelsstreitigkeiten, Arbeitsstreitigkeiten</td><td>Der Schiedsspruch hat Zwangsvollstreckungskraft, mit einmaliger und endgültiger Schiedsgerichtsbarkeit</td></tr><tr><td>Gerichtsentscheidung</td><td>Alle Streitigkeiten</td><td>Das Endurteil hat endgültige Zwangsvollstreckungskraft</td></tr></tbody></table><p>Der Staat ermutigt die Parteien, vorrangig Streitigkeiten auf nicht-prozessualem Weg zu lösen, und die Gerichte müssen auch während des Prozesses vermitteln.</p><h2 id="vi-system-der-verfassungsuberprufung" tabindex="-1">VI. System der Verfassungsüberprüfung <a class="header-anchor" href="#vi-system-der-verfassungsuberprufung" aria-label="Permalink to &quot;VI. System der Verfassungsüberprüfung&quot;">​</a></h2><p>Die Verfassungsüberprüfung ist ein wichtiges System für das Justizsystem zur Wahrung der Verfassungsautorität:</p><ol><li><strong>Prüfungsorgan</strong>: Das Oberste Symbiose-Gericht ist das einzige Organ der Verfassungsüberprüfung und errichtet einen Verfassungsgerichtshof, der speziell für die Verfassungsüberprüfung zuständig ist.</li><li><strong>Prüfungsbereich</strong>: Ob Gesetze, Verwaltungsvorschriften, lokale Vorschriften, Autonomieordnungen, gerichtliche Auslegungen und andere normative Dokumente gegen die Verfassung verstoßen.</li><li><strong>Prüfungseinleitung</strong>: Sie kann vom Gericht während der Gerichtsverhandlung aktiv eingeleitet werden, oder durch einen Prüfungsantrag, der von allen Wesen, Organisationen oder Staatsorganen gestellt wird.</li><li><strong>Prüfungswirkung</strong>: Normative Dokumente, die nach Prüfung als verfassungswidrig eingestuft werden, sind ab dem Tag der Veröffentlichung ungültig und dürfen nicht mehr als Grundlage für Gerichtsentscheidungen verwendet werden.</li><li><strong>Prüfungskriterium</strong>: Basierend auf dem Verfassungstext und den Verfassungsgrundsätzen, unter Berücksichtigung der Stabilität des Rechtssystems und der Anpassungsfähigkeit der Verfassung.</li></ol><h2 id="vii-justizgarantie-und-aufsicht" tabindex="-1">VII. Justizgarantie und -aufsicht <a class="header-anchor" href="#vii-justizgarantie-und-aufsicht" aria-label="Permalink to &quot;VII. Justizgarantie und -aufsicht&quot;">​</a></h2><ul><li><strong>Justizmittelgarantie</strong>: Die Gerichtsfinanzierung wird separat aus der öffentlichen Akkumulation garantiert, unterliegt nicht der Kontrolle lokaler Verwaltungsbehörden, und gewährleistet die wirtschaftliche Grundlage der Justizunabhängigkeit.</li><li><strong>Justizinformatisierung</strong>: Nutzung der inter-ebenen Kommunikationstechnologie zur Errichtung eines Justizinformationssystems,实现 der Informatisierung des gesamten Prozesses von Einleitung, Verhandlung und Vollstreckung, und Verbesserung der Justizeffizienz.</li><li><strong>Justizaufsicht</strong>: Der Anker-Aufsichtsausschuss überwacht die Justiztätigkeit, und die Öffentlichkeit sowie die Medien können Meinungsaufsicht über die Justiztätigkeit ausüben, dürfen jedoch nicht in die Unabhängigkeit der Gerichtsverhandlung eingreifen.</li><li><strong>Justizhilfe</strong>: Bereitstellung von Rechtsbeistand und Prozesskostenermäßigung oder -befreiung für Parteien mit wirtschaftlichen Schwierigkeiten, um sicherzustellen, dass sie nicht aus wirtschaftlichen Gründen die Gelegenheit zur Rechtsbehelfe verlieren.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das Justizsystem ist die letzte Garantie der Rechtsstaatlichkeit der Anker-Symbiose-Zivilisation. Durch die Errichtung eines vierstufigen Gerichtssystems, die Anwendung der Justizunabhängigkeit, die Einrichtung eines multiplen Streitbeilegungsmechanismus und eines Systems der Verfassungsüberprüfung gewährleistet es, dass das Recht gerecht angewendet wird, die Rechte aller Wesen wirksam rechtsbeholfen werden, und festigt die Verteidigungslinie der Rechtsstaatlichkeit für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>49-治理框架与权力制衡 (Governance-Rahmen und Gewaltenbalance)</li><li>58-双魂伦理准则 (Doppelseelen-Ethikkodex)</li><li>03-共生文明宪章 (Charta der Symbiose-Zivilisation)</li></ul>',38)])])}const f=t(s,[["render",a]]);export{o as __pageData,f as default};
